from __future__ import annotations; from datetime import UTC, datetime, timedelta; from data_engine.quality import surface_proof; from data_engine.quality.surface_proof import prove, summary_lines; NOW = datetime(2026, 9, 16, 0, 15, tzinfo=UTC); NEW = "capture-run:" + "a" * 64; OLD = "capture-run:" + "b" * 64; QQQ = "capture-run:" + "c" * 64; TOPT_UNIVERSE = "universe:topt-us-2026-03-31"; QQQ_UNIVERSE = "universe:qqq-us-2026"; REPORT = {"questions": {"q1": {"answered": 18, "unavailable": {"x": 2}, "missing": 0}}}
class _Tables:
    def __init__( self, *, strategy=None, themes=None, holdings=None, funds=0, coverage=(), partitions=0, theme_runs=None, theme_universes=None, environment="staging", ): self.strategy, self.themes, self.holdings, self.funds, self.coverage = ( strategy, themes, holdings, funds, coverage, ); self.partitions = partitions; self.environment = environment; self.theme_runs = set(theme_runs) if theme_runs is not None else ({themes} if themes else set()); self.theme_universes = ( set(theme_universes) if theme_universes is not None else ({"universe:topt-us-"} if self.theme_runs else set()) ); self._rows: list = []
    def execute(self, sql, params=()):
        text = " ".join(sql.split())
        if text == "select environment from mart.environment_identity": self._rows = [(self.environment,)]
        elif "from mart.current_pointer p join mart.issuer_theme_purity" in text: self._rows = [(params[2].removesuffix("%") in self.theme_universes,)]
        elif "from mart.issuer_theme_purity where run_id = %s" in text: self._rows = [(params[0] in self.theme_runs,)]
        elif "mart.governed_strategy_run" in text: self._rows = [(self.strategy, "strategy-run:x")] if self.strategy else []
        elif "from mart.issuer_theme_purity" in text and "group by run_id" in text: self._rows = [(self.themes, NOW)] if self.themes else []
        elif "from mart.question_coverage_report" in text: self._rows = list(self.coverage)
        elif "from mart.current_pointer_head" in text or "from mart.served_head" in text: self._rows = [(self.holdings,)] if self.holdings else []
        elif "from mart.fund_virtual_company" in text: self._rows = [(self.funds,)]
        elif "from staging.issuer_segment_revenue_facts" in text: self._rows = [(self.partitions,)]
        else: raise AssertionError(f"unexpected query: {text[:80]}")
        return self
    def fetchone(self): return self._rows[0] if self._rows else None
    def fetchall(self): return list(self._rows)
def _heads(monkeypatch, *, topt=NEW, qqq=QQQ, topt_cutoff=NOW, qqq_cutoff=NOW):
    def governed_head(_connection, *, universe_prefix): is_topt = universe_prefix.startswith("universe:topt"); run = topt if is_topt else qqq; universe_id = TOPT_UNIVERSE if is_topt else QQQ_UNIVERSE; cutoff = topt_cutoff if is_topt else qqq_cutoff; return None if run is None else surface_proof.GovernedHead(universe_id, run, cutoff)
    monkeypatch.setattr(surface_proof, "governed_head", governed_head)
def _reports(monkeypatch, fresh): monkeypatch.setattr(surface_proof, "compile_report", lambda *_a, **_k: fresh)
def test_a_surface_serving_the_previous_head_is_a_mismatch_by_name(monkeypatch) -> None: _heads(monkeypatch, qqq=None); _reports(monkeypatch, REPORT); tables = _Tables(strategy=NEW, themes=OLD, coverage=[(TOPT_UNIVERSE, OLD, REPORT)]); verdicts = prove(tables, executed_at=NOW); by_surface = {v.surface: v for v in verdicts}; assert by_surface["/research/rankings, /strategy, /compare, /trace, /coverage"].ok; assert not by_surface["/research/themes"].ok; assert not by_surface["/admin/datahub coverage [topt]"].ok; assert by_surface["/research/holdings"].ok, "no QQQ head and nothing served: not run here, not a mismatch"; assert summary_lines(verdicts)[-1].endswith("2 do not"); assert summary_lines(verdicts)[1].startswith("MISMATCH /research/themes: serves capture-run:bbbbbbbbbbbb")
