def _db():
    import os; import psycopg; import pytest; from data_engine.config import settings
    try: return psycopg.connect(settings.database_url, connect_timeout=3, autocommit=False)
    except psycopg.OperationalError:
        if os.environ.get("DATABASE_URL") or os.environ.get("TRUEALPHA_REQUIRE_RUNTIME"): raise
        pytest.skip("no local Postgres")
def _seed_head( connection, *, universe_id: str, run_id: str, previous: str | None = None, sequence: int = 0 ) -> datetime: import hashlib; digest = run_id.split(":", 1)[1]; connection.execute( "\n        insert into staging.evidence_nodes (node_id, kind, content_sha256, valid_from, transaction_time, recorded_at)\n        values (%s, 'capture_run', %s, %s, %s, %s)\n        on conflict (node_id) do nothing\n        ", (run_id, digest, NOW.date(), NOW, NOW), ); pointer = hashlib.sha256(f"{universe_id}|{run_id}".encode()).hexdigest(); return connection.execute( "\n        insert into mart.current_pointer\n            (pointer_id, content_sha256, environment, universe_id, universe_version, factor_id,\n             target_run_id, sequence, previous_run_id, advanced_at)\n        values (%s, %s, 'production', %s, 'v1', 'gross_profit_per_employee', %s, %s, %s, %s)\n        returning created_at\n        ", (f"current-pointer:{pointer}", pointer, universe_id, run_id, sequence, previous, NOW), ).fetchone()[0]
def _store_report(connection, *, universe_id: str, run_id: str) -> None: import hashlib; digest = hashlib.sha256(f"report|{universe_id}|{run_id}".encode()).hexdigest(); connection.execute( "\n        insert into mart.question_coverage_report\n            (report_id, content_sha256, universe_id, run_id, cutoff, requirements_sha256, payload)\n        values (%s, %s, %s, %s, %s, %s, '{}'::jsonb)\n        ", (f"question-coverage-report:{digest}", digest, universe_id, run_id, NOW, "0" * 64), )
def test_a_head_recorded_minutes_ago_without_its_reports_is_settling_and_then_is_not(monkeypatch) -> None:
    from data_engine.quality.surface_proof import fresh_heads_without_reports; universe_id = "universe:topt-settling-test"; run = "capture-run:" + "e" * 64
    def governed_head(_connection, *, universe_prefix):
        if universe_prefix.startswith("universe:topt"): return surface_proof.GovernedHead(universe_id, run, NOW)
        return None
    monkeypatch.setattr(surface_proof, "governed_head", governed_head); grace = timedelta(minutes=10); connection = _db()
    try: recorded = _seed_head(connection, universe_id=universe_id, run_id=run); _store_report(connection, universe_id=universe_id, run_id="capture-run:" + "f" * 64); settling = fresh_heads_without_reports(connection, now=recorded + timedelta(minutes=3), grace=grace); assert list(settling) == ["topt"]; assert settling["topt"] == f"head {run[:24]} recorded 3 min ago; its reports are not written yet"; assert fresh_heads_without_reports(connection, now=recorded + timedelta(minutes=11), grace=grace) == {}; _store_report(connection, universe_id=universe_id, run_id=run); assert fresh_heads_without_reports(connection, now=recorded + timedelta(minutes=1), grace=grace) == {}
    finally: connection.rollback(); connection.close()
def _seed_theme_row(connection, *, run_id: str, cutoff: datetime) -> None: connection.execute( "\n        insert into mart.issuer_theme_purity\n            (run_id, issuer_id, cik, theme_id, theme, definition_version, definition_sha256, cutoff,\n             period_end, partition_id, theme_share, consolidated_revenue, in_theme_revenue,\n             out_of_theme_revenue, unclassified_revenue, partition_residual, segments, confidence,\n             extractor, availability_status, source_evidence_status, factor_validation_status)\n        values (%s, 'issuer:themes-910-test', %s, 'ai-compute', 'AI compute', 'v1', %s, %s,\n                %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,\n                'rule:themes-910-test', 'available', 'verified', 'accepted')\n        ", ( run_id, 910, "0" * 64, cutoff, cutoff.date(), "segment-partition:" + "0" * 64, "0.5", "100", "50", "50", "0", "0", 2, "0.9", ), )
def test_the_theme_lane_covers_a_universe_once_a_run_its_pointer_named_has_rows(monkeypatch) -> None:
    from data_engine.quality.surface_proof import themes_verdict; topt_universe, qqq_universe = "universe:topt-us-themes-910-test", "universe:qqq-us-themes-910-test"; topt_run, qqq_old, qqq_run = ("capture-run:" + digit * 64 for digit in "789"); heads = { "topt": surface_proof.GovernedHead(topt_universe, topt_run, TOPT_CUTOFF), "universe-list:qqq": surface_proof.GovernedHead(qqq_universe, qqq_run, QQQ_CUTOFF), }; connection = _db()
    try: _seed_head(connection, universe_id=topt_universe, run_id=topt_run); _seed_head(connection, universe_id=qqq_universe, run_id=qqq_old); _seed_head(connection, universe_id=qqq_universe, run_id=qqq_run, previous=qqq_old, sequence=1); _seed_theme_row(connection, run_id=topt_run, cutoff=TOPT_CUTOFF); never_covered = themes_verdict(connection, heads, topt_run); assert (never_covered.state, never_covered.universe) == ("MATCH", "topt"); _seed_theme_row(connection, run_id=qqq_old, cutoff=QQQ_CUTOFF - timedelta(days=1)); waiting = themes_verdict(connection, heads, topt_run); assert (waiting.state, waiting.universe, waiting.expected_run) == ("MISMATCH", "universe-list:qqq", qqq_run); assert waiting.detail.startswith( "the universe-list:qqq head, the newest of a universe with theme rows, has none" ); _seed_theme_row(connection, run_id=qqq_run, cutoff=QQQ_CUTOFF); landed = themes_verdict(connection, heads, qqq_run); assert (landed.state, landed.universe) == ("MATCH", "universe-list:qqq")
    finally: connection.rollback(); connection.close()
_FILL_ONLY_CUTOFF = datetime(2099, 1, 2, tzinfo=UTC); _REAL_CUTOFF = datetime(2099, 1, 1, tzinfo=UTC)
def _seed_theme_fill(connection, *, run_id: str, cutoff: datetime) -> None:
    import uuid; from truealpha_contracts.theme_purity import THEMES; issuer_id = str(uuid.uuid4())
    for t in THEMES.values(): connection.execute( "\n            insert into mart.issuer_theme_purity (\n                run_id, issuer_id, cutoff, reason_codes, theme_id, theme, definition_version, definition_sha256,\n                segments, confidence, extractor, availability_status, source_evidence_status, factor_validation_status\n            ) values (%s, %s, %s, %s, %s, %s, %s, %s, 0, 0, 'lane:unvisited:v1', 'unavailable', 'degraded', 'not_evaluated')\n            ", ( run_id, issuer_id, cutoff, ["no_segment_partition"], t.theme_id, t.theme, t.factor_version, t.content_sha256, ), )
    count = connection.execute( "select count(*) from mart.issuer_theme_purity where run_id = %s and extractor = 'lane:unvisited:v1'", (run_id,) ).fetchone(); assert count == (len(THEMES),), "one fill row for each governed theme"
def _typescript_query(name: str, rel_path: str = "apps/app-web/src/server/mart/theme-purity.ts") -> str:
    import re; from pathlib import Path; source = (Path(__file__).resolve().parents[3] / rel_path).read_text()
    match = re.search(rf"const {name} = `(?P<sql>.*?)`;", source, re.S)
    assert match is not None, f"{rel_path} no longer declares {name}"; return match.group("sql").replace("$1", "%s")
